long long sum[4*N], lz[4*N];               // 구간 합과, 자식에게 아직 내려보내지 않은 덧셈
void apply(int x, int len, long long v) { sum[x] += v * len; lz[x] += v; }
void push(int x, int s, int e) {          // 미뤄 둔 덧셈을 두 자식에게 내려보낸다
    if (!lz[x]) return;
    int m = (s + e) / 2;
    apply(2*x, m - s + 1, lz[x]); apply(2*x+1, e - m, lz[x]); lz[x] = 0;
}
void update(int x, int s, int e, int l, int r, long long v) {
    if (r < s || e < l) return;
    if (l <= s && e <= r) { apply(x, e - s + 1, v); return; }   // 완전히 덮이면 여기서 멈춘다
    push(x, s, e);
    int m = (s + e) / 2;
    update(2*x, s, m, l, r, v); update(2*x+1, m+1, e, l, r, v);
    sum[x] = sum[2*x] + sum[2*x+1];
}
long long query(int x, int s, int e, int l, int r) {
    if (r < s || e < l) return 0;
    if (l <= s && e <= r) return sum[x];
    push(x, s, e);
    int m = (s + e) / 2;
    return query(2*x, s, m, l, r) + query(2*x+1, m+1, e, l, r);
}

